css:
.rm-t-fresh-mint{padding:0 0 46px;color:#274842;background:#fbfefd;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;}
.rm-t-fresh-mint .rm-head{margin:34px 42px 0;padding:26px 28px 24px;background:linear-gradient(135deg,#e9f8f4 0%,#f6fdfb 70%,#ffffff 100%);border:1px solid #dff0eb;border-radius:18px;}
.rm-t-fresh-mint .rm-name{font-size:34px;font-weight:700;letter-spacing:.04em;line-height:1.2;color:#1f5f55;}
.rm-t-fresh-mint .rm-role{display:inline-block;margin-top:10px;padding:3px 12px;border-radius:999px;background:#d8f1e9;color:#2f7d6f;font-size:12px;letter-spacing:.02em;}
.rm-t-fresh-mint .rm-contact{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 20px;margin-top:18px;}
.rm-t-fresh-mint .rm-k{padding:1px 8px;border-radius:999px;background:#eefaf6;color:#5c8f85;font-size:9.5px;}
.rm-t-fresh-mint .rm-v{font-size:11.5px;color:#35564f;}
.rm-t-fresh-mint .rm-body{padding:0 42px;}
.rm-t-fresh-mint .rm-sec{margin-top:14px;padding:15px 20px 16px;background:#ffffff;border:1px solid #e4f2ee;border-radius:14px;box-shadow:0 2px 10px rgba(95,160,148,.06);}
.rm-t-fresh-mint .rm-sec-h{margin:0 0 10px;padding-bottom:8px;border-bottom:1px dashed #dcefe9;gap:0;}
.rm-t-fresh-mint .rm-sec-t{font-size:12.5px;font-weight:700;letter-spacing:.1em;color:#1f5f55;}
.rm-t-fresh-mint .rm-sec-t::before{content:"";display:inline-block;width:8px;height:8px;margin-right:8px;border-radius:3px;background:#63b4a6;vertical-align:0;}
.rm-t-fresh-mint .rm-item{margin-bottom:11px;}
.rm-t-fresh-mint .rm-item-t{font-size:13.5px;font-weight:600;color:#1f5f55;}
.rm-t-fresh-mint .rm-item-role{font-size:12px;color:#5b817a;}
.rm-t-fresh-mint .rm-date{padding:0 7px;border-radius:6px;background:#f0faf7;color:#5c8f85;font-size:10.5px;}
.rm-t-fresh-mint .rm-item-sub{font-size:11.5px;color:#648a83;}
.rm-t-fresh-mint .rm-edu-courses{font-size:11px;color:#648a83;}
.rm-t-fresh-mint .rm-bullets{padding-left:14px;}
.rm-t-fresh-mint .rm-bullets li{margin:2px 0;}
.rm-t-fresh-mint .rm-bullets li::marker{color:#9ed4c8;}
.rm-t-fresh-mint .rm-summary{font-size:12.5px;line-height:1.75;color:#35564f;}
.rm-t-fresh-mint .rm-tags{gap:6px;flex-wrap:wrap;}
.rm-t-fresh-mint .rm-tag{padding:1px 10px;border-radius:999px;background:#eefaf6;border:1px solid #cfece4;color:#2f7d6f;font-size:11px;}
.rm-t-fresh-mint .rm-skill-row{grid-template-columns:96px minmax(0,1fr);gap:10px;margin-bottom:8px;}
.rm-t-fresh-mint .rm-skill-k{font-size:11.5px;font-weight:600;color:#2f7d6f;}
.rm-t-fresh-mint .rm-award-row{margin-bottom:6px;}
.rm-t-fresh-mint .rm-award-t{font-size:12.5px;color:#1f5f55;}
.rm-t-fresh-mint .rm-award-desc{font-size:11px;color:#648a83;}
.rm-t-fresh-mint .rm-sec-campus{padding-bottom:14px;}
.rm-t-fresh-mint .rm-sec-hobbies{padding-bottom:14px;}
